```go
package main

import (
    "errors"
    "fmt"
)

var ErrNotFound = errors.New("not found")

func load(id int) error {
    return fmt.Errorf("load user %d: %w", id, ErrNotFound)
}

func main() {
    err := load(42)
    fmt.Println(err)
    fmt.Println(errors.Is(err, ErrNotFound))
}
```
The output contains user `42`, and the sentinel check remains true because `%w` retained the cause.

```go
package main

import (
    "errors"
    "fmt"
)

var ErrNotFound = errors.New("not found")

func storage() error {
    return fmt.Errorf("record 42: %w", ErrNotFound)
}

func service() error {
    return fmt.Errorf("load profile: %w", storage())
}

func main() {
    fmt.Println(service())
    fmt.Println(errors.Is(service(), ErrNotFound))
}
```
The final check prints `true` even though two useful descriptions surround the original sentinel.
